const owners={tax:'Kế toán / người phụ trách thuế',accounting:'Kế toán / người phụ trách tài chính',labor:'Nhân sự / người phụ trách lao động',insurance:'Nhân sự và kế toán',company:'Người đại diện / người phụ trách pháp lý',commerce:'Người phụ trách kinh doanh và pháp lý',data:'Người phụ trách dữ liệu cá nhân',fire:'Người phụ trách cơ sở và an toàn',environment:'Người phụ trách môi trường',food:'Người phụ trách an toàn thực phẩm'};
// Older generated guides appended this line to every step. Recording gaps and owners belongs in the step note,
// not in a tick item, so it is dropped wherever it appears.
export const BOILERPLATE_CHECK='Ghi kết quả đối chiếu, điểm thiếu và người phụ trách xử lý.';
// Wording left over from the draft (pilot) stage; meaningless once a checklist is published.
const DRAFT_SENTENCE=/s*Bản nháp không tự yêu cầu nộp tài liệu cho cơ quan nhà nước.?/giu;
export const cleanText=x=>String(x??'').replace(DRAFT_SENTENCE,'').trim();
const sameText=(a,b)=>asSentence(a).toLocaleLowerCase('vi')===asSentence(b).toLocaleLowerCase('vi');
const asSentence=x=>{const t=String(x).trim().replace(/[\s.;]+$/,'');return t?t[0].toLocaleUpperCase('vi')+t.slice(1)+'.':'';};
// One check per clause separated by ';' (each is a separate action in the drafted Vietnamese text).
export function stepChecks(detail){const parts=String(detail).split(/;\s*/).map(asSentence).filter(Boolean);return parts.length?parts:[asSentence(detail)];}
// Presentation-only cleanup: never changes the stored version, so it cannot invalidate saved pilot progress.
export function cleanGuide(guide){const proof=cleanText(guide.proof);return {...guide,proof,steps:guide.steps.map(s=>{const checks=s.checks.filter(x=>String(x).trim()!==BOILERPLATE_CHECK).map(asSentence).filter(Boolean),evidence=cleanText(s.evidence);return {...s,evidence:sameText(evidence,proof)?'':evidence,checks:checks.length?checks:stepChecks(s.detail)};})};}
export function checklistGuide(c){
 if(c.guide)return cleanGuide(c.guide);
 return {question:`Việc “${c.title}” đã được đối chiếu với hồ sơ thực tế chưa?`,proof:cleanText(c.evidenceInstructions),done:'Đã đánh giá đủ từng điểm, xử lý các điểm thiếu, ghi bằng chứng và lý do cho tiêu chí không áp dụng.',owner:owners[c.group]||'Người phụ trách được doanh nghiệp phân công',timing:'Theo mốc hiển thị của công việc; kiểm tra lại khi hồ sơ, kỳ hoặc căn cứ thay đổi. Mục chưa có hạn cần theo dõi riêng từng sự kiện phát sinh.',steps:c.steps.map(s=>({detail:s,when:'',checks:stepChecks(s),evidence:'',provisionIds:[]}))};
}
export function reviewState(saved={},legacySteps=[]){return {steps:saved.steps||legacySteps.map(index=>({index,result:'pass',note:''})),evidenceNote:saved.evidenceNote||'',notApplicableReason:saved.notApplicableReason||'',reminderDate:saved.reminderDate||null,owner:saved.owner||''};}
export function renderVerificationSummary(c,citations,{missingFacts=[],explanation='',verificationHtml='',esc,icon,cite}){
 const g=checklistGuide(c);
 if(verificationHtml)return `<div class="detail-intro"><strong>Tóm tắt để xác minh</strong><p>${esc(c.action)}</p></div>${verificationHtml}<p class="detail-hint">Đủ điều kiện áp dụng thì mở checklist để xử lý. Chưa rõ thì giữ lại ở Cần xác minh.</p><details class="sheet-section"><summary>Căn cứ và tóm tắt tham khảo</summary><p>${esc(g.proof)}</p><p>Người phụ trách gợi ý: ${esc(g.owner)}</p><div class="basis-list">${citations.map(cite).join('')}</div></details>`;
 return `<div class="detail-intro"><strong>Tóm tắt để xác minh</strong><p>${esc(g.question)}</p></div><div class="verification-brief"><div class="verification-brief-head"><span class="verification-icon">${icon('help',19)}</span><div><strong>Đây là bước xác minh phạm vi</strong><p>Chưa cần đánh từng checklist. Hãy đọc tóm tắt, chuẩn bị thông tin cần thiết rồi xác minh việc này có thuộc phạm vi doanh nghiệp hay không.</p></div></div><div class="verification-facts"><div><span>VẤN ĐỀ CẦN LÀM RÕ</span><strong>${esc(g.question)}</strong></div><div><span>THÔNG TIN CẦN CÓ</span><strong>${esc(missingFacts.length?missingFacts.join(', '):g.proof)}</strong><p>${esc(g.proof)}</p></div><div><span>NGƯỜI PHỤ TRÁCH GỢI Ý</span><strong>${esc(g.owner)}</strong></div><div><span>THỜI ĐIỂM RÀ SOÁT</span><strong>${esc(g.timing)}</strong></div></div>${explanation?`<p>${esc(explanation)}</p>`:''}</div><div class="sheet-section"><h3>Căn cứ tham khảo</h3><div class="basis-list">${citations.map(cite).join('')}</div><p class="detail-hint">Đây là bản tóm tắt để xác minh phạm vi, chưa phải kết luận tuân thủ.</p></div>`;
}
export function renderGuide(c,citations,{review={},readOnly=false,reviewer=false,controls='',ownerControls='',openGroups,esc,icon,cite}){
 const g=checklistGuide(c),steps=review.steps||[],assessed=steps.length;
 const cards=g.steps.map((s,i)=>{
  const result=steps.find(x=>x.index===i),links=(s.provisionIds||[]).map(id=>citations.find(c=>c.provisionId===id)).filter(Boolean);
  return `<article class="review-step ${esc(result?.result||'')}" data-review-index="${i}"><div class="review-step-head"><span class="step-number-mini">${String(i+1).padStart(2,'0')}</span><h4>${esc(c.steps[i])}</h4>${reviewer?`<button type="button" class="text-action" data-guide-edit="${i}">Chỉnh sửa điểm này</button>`:''}</div>${s.when?`<div class="review-when">CHỈ KHI · ${esc(s.when)}</div>`:''}${!sameText(s.detail,c.steps[i])?`<p>${esc(s.detail)}</p>`:''}${s.checks.some(x=>!sameText(x,c.steps[i])&&!sameText(x,s.detail))?`<div class="review-checks"><strong>Cần đối chiếu lần lượt</strong><ul>${s.checks.filter(x=>!sameText(x,c.steps[i])&&!sameText(x,s.detail)).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${s.evidence&&s.evidence!==g.proof?`<div class="review-evidence"><strong>Bằng chứng cần đối chiếu</strong><span>${esc(s.evidence)}</span></div>`:''}${links.length?`<div class="review-refs">${links.map(cite).join('')}</div>`:''}<div class="review-actions" role="group" aria-label="Kết quả mục ${i+1}">${[['pass','Đạt'],['issue','Cần xử lý'],['na','Không áp dụng']].map(([v,label])=>`<button type="button" data-review-result="${v}" data-review-step="${i}" class="${result?.result===v?'selected '+v:''}" aria-pressed="${result?.result===v}" ${readOnly?'disabled':''}>${label}</button>`).join('')}</div>${result||reviewer?`<label class="review-note">${result?.result==='na'?'Lý do không áp dụng (bắt buộc)':result?.result==='issue'?'Điểm thiếu / việc cần xử lý':'Ghi chú bằng chứng (tùy chọn)'}<textarea name="step-note-${i}" rows="2" maxlength="2000" ${readOnly?'disabled':''}>${esc(result?.note||'')}</textarea></label>`:''}</article>`;
 });
 const grouped=Array.from({length:Math.ceil(cards.length/4)},(_,index)=>{const start=index*4,end=Math.min(start+4,cards.length);return `<details class="review-group" data-review-group="${index}" ${(openGroups?openGroups.includes(index):index===0)?'open':''}><summary><span>Nhóm ${index+1}</span><strong>Mục ${start+1}–${end}</strong><small>${steps.filter(x=>x.index>=start&&x.index<end).length}/${end-start} đã đánh giá</small>${icon('chevron',16)}</summary><div>${cards.slice(start,end).join('')}</div></details>`;}).join('');
 return `<div class="detail-intro"><strong>Câu hỏi cần làm rõ</strong><p>${esc(g.question)}</p></div><div class="sheet-section"><h3>1. Trạng thái công việc</h3>${controls}<p>Đánh giá quá trình rà soát theo bằng chứng; kết quả không tự chứng nhận tuân thủ.</p><p><strong>Việc cần thực hiện:</strong> ${esc(c.action)}</p><p><strong>Phạm vi / ngoại lệ:</strong> ${esc(c.exceptions)}</p></div><div class="sheet-section"><div class="detail-section-row"><h3>2. Các điểm cần kiểm tra</h3><span>${assessed}/${g.steps.length} mục đã đánh giá</span></div><p class="review-guidance">“Không áp dụng” tại mỗi điểm chỉ dành cho tiêu chí đó và cần ghi lý do. Quyết định cho toàn bộ công việc ở cuối trang.</p><div class="step-checklist detailed">${grouped}</div></div><div class="sheet-section"><h3>3. Ghi chú bằng chứng và điều kiện kết thúc</h3><p><strong>Nên lưu nội bộ:</strong> ${esc(g.proof)}</p><p><strong>Kết thúc rà soát khi:</strong> ${esc(g.done)}</p><label class="review-note">Ghi chú vị trí lưu hoặc mã hồ sơ<textarea name="evidenceNote" rows="3" maxlength="2000" ${readOnly?'disabled':''}>${esc(review.evidenceNote||'')}</textarea></label></div><div class="sheet-section"><h3>4. Người phụ trách và nhắc việc</h3><p><strong>Gợi ý:</strong> ${esc(g.owner)}</p><p>${esc(g.timing)}</p>${ownerControls}</div><div class="sheet-section"><h3>5. Nguồn văn bản và mức tin cậy</h3><div class="basis-list">${citations.map(cite).join('')}</div><p class="detail-hint">Căn cứ chung của checklist. Chỉ gắn căn cứ cho từng điểm khi đã xác định được liên hệ với điều khoản; không mặc định mọi bước đều dựa vào mọi trích dẫn.</p></div>${review.notApplicableReason?`<div class="sheet-section"><h3>Lý do toàn bộ công việc không áp dụng</h3><p>${esc(review.notApplicableReason)}</p></div>`:''}`;
}
